use std::error::Error;
use std::fmt;
use std::fs;
use std::io;
use std::num::ParseIntError;

/// 1) 应用层统一错误类型：用枚举穷举所有可能的失败
#[derive(Debug)]
enum AppError {
    /// 底层 I/O 失败（读文件、写文件）
    Io(io::Error),
    /// 某一行解析失败，保留行号上下文 + 原始错误
    Parse { line_no: usize, source: ParseIntError },
    /// 业务规则：输入为空
    Empty,
}

/// 2) 实现 Display：给出面向用户的错误信息
impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::Io(e) => write!(f, "I/O error: {}", e),
            AppError::Parse { line_no, .. } => {
                write!(f, "parse error at line {}", line_no)
            }
            AppError::Empty => write!(f, "input is empty"),
        }
    }
}

/// 3) 实现 Error：通过 source() 串起错误链
impl Error for AppError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            AppError::Io(e) => Some(e),
            AppError::Parse { source, .. } => Some(source),
            AppError::Empty => None,
        }
    }
}

/// 4) 为底层错误实现 From，让 `?` 自动完成类型转换
impl From<io::Error> for AppError {
    fn from(e: io::Error) -> Self {
        AppError::Io(e)
    }
}

/// 读取文件，逐行解析成整数并求和
fn sum_file(path: &str) -> Result<i32, AppError> {
    // `?` 这里会调用 From::<io::Error>::from 转换成 AppError
    let content = fs::read_to_string(path)?;

    let mut total = 0;
    let mut count = 0;

    for (idx, line) in content.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        // 需要额外上下文（行号）时手动 map_err
        let n: i32 = line.parse().map_err(|source| AppError::Parse {
            line_no: idx + 1,
            source,
        })?;
        total += n;
        count += 1;
    }

    // 业务级错误：直接构造枚举变体返回
    if count == 0 {
        return Err(AppError::Empty);
    }
    Ok(total)
}

/// 递归打印整条错误链，方便排查问题根因
fn report(mut e: &dyn Error) {
    eprintln!("error: {}", e);
    while let Some(src) = e.source() {
        eprintln!("  caused by: {}", src);
        e = src;
    }
}

fn main() {
    // 准备一个示例文件
    fs::write("numbers.txt", "10\n20\n30\n").unwrap();

    match sum_file("numbers.txt") {
        Ok(v) => println!("sum = {}", v),
        Err(e) => report(&e),
    }

    // 演示错误链：文件不存在
    match sum_file("missing.txt") {
        Ok(v) => println!("sum = {}", v),
        Err(e) => report(&e),
    }

    // 演示带上下文的解析错误
    fs::write("bad.txt", "10\nabc\n30\n").unwrap();
    match sum_file("bad.txt") {
        Ok(v) => println!("sum = {}", v),
        Err(e) => report(&e),
    }
}

