use std::error::Error;
use std::fmt;

#[derive(Debug)]
enum E { A, B }

impl fmt::Display for E {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            E::A => write!(f, "alpha"),
            E::B => write!(f, "beta"),
        }
    }
}

impl Error for E {}

fn f() -> Result<i32, E> {
    let n: i32 = "12a".parse().map_err(|_| E::B)?;
    Ok(n)
}

fn main() {
    match f() {
        Ok(v) => println!("ok {}", v),
        Err(e) => println!("err {:?} {}", e, e),
    }
}
